using System.Diagnostics;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Rooms;

namespace CombatSolver;

internal static partial class CombatSearchCoordinator
{
    internal static PrimarySearchIncumbent? BuildRefinementPrimarySearchIncumbent(
        CombatRootSnapshot root, SearchPolicySnapshot policy,
        SolverPotionPolicy? memberPotionPolicyOverride, SolverResult incumbent)
        => !policy.DisableRefinementIncumbentForTesting
            && (root.CanCertifyRemainingHealing || root.UsesKnownNativeHealingPolicy)
            && IsReusablePotionFreeVictory(policy, memberPotionPolicyOverride, incumbent)
                ? BuildPrimarySearchIncumbent(root, policy, incumbent)
                : null;

    private static bool IsReusablePotionFreeVictory(
        SearchPolicySnapshot policy, SolverPotionPolicy? memberPotionPolicyOverride, SolverResult result)
        => (memberPotionPolicyOverride ?? policy.PotionPolicy)
                is SolverPotionPolicy.Disabled or SolverPotionPolicy.Smart
            && !policy.PotionStrategy.HasForcedDirectives
            && result.ResultScope == SolverResultScope.SearchCompletion
            && result.BoundaryReason == SearchBoundaryReason.None
            && result.ExplicitPotionCount == 0
            && !result.Snapshot.HasRisk
            && result.Snapshot.ProjectedDeathSaveUseCount == 0
            && result.CombatEndedTurn.HasValue
            && IsCompleteVictory(result);

    /// <summary>
    /// 主搜索的宽度组合接线，开关开关两种情况都走这里，所以逐成员诊断和
    /// <see cref="BeamWidthPortfolioTelemetry" /> 在关闭时同样存在（单成员一行）。
    /// </summary>
    /// <remarks>
    /// <para>
    /// 没有提前计划胜利时，首个成员沿用原 profile。提前计划已消费的节点计入请求账本，
    /// 首个成员获得剩余节点与时间，并使用该完整胜利的既有 incumbent 界；宽度和排名不变。
    /// 其余成员仍使用组合器的宽度、排名策略及共享余量。
    /// </para>
    /// <para>
    /// 界面的中途路线走 <c>SolverProgress</c> 回调：搜索发布进度，运行时把进度里的
    /// <c>SpeculativeRoutePreview</c> / <c>CurrentTurnPreview</c> 渲染出来。因此基线成员一完成就用
    /// <paramref name="publishBaseline" />（协调器已有的 interim 回调）把完整结果推出去，
    /// 玩家看到第一条路线的时刻不受后面的精炼影响。
    /// </para>
    /// <para>
    /// 精炼成员的准入全部交给 <see cref="BeamWidthPortfolioGate" />：基线必须已经把这一宽度搜干净、
    /// 自己没吃掉超过四分之一的时间预算，剩余节点和剩余时间满足原有门槛，才会启动。
    /// 内存由每个成员执行期间的逐批预约和 Runtime 回收检查点处理。成员顺序执行。
    /// </para>
    /// </remarks>
    private static SolverResult RunBeamWidthPortfolioPass(
        SearchPassContext context,
        Func<SolverSearchProfile, bool, PrimarySearchIncumbent?, SolverResult> solveMember,
        Action<SolverResult>? publishBaseline,
        SolverPotionPolicy? memberPotionPolicyOverride,
        SolverResult? initialPlanIncumbent)
    {
        CombatRootSnapshot root = context.Root;
        SearchPolicySnapshot policy = context.Policy;
        SolverSearchProfile profile = context.Profile;
        Stopwatch passClock = context.Clock;
        CancellationToken cancellationToken = context.CancellationToken;
        SearchRequestWorkTotals totals = context.Budget.WorkTotals;
        BeamWidthPortfolioTelemetry telemetry = policy.PortfolioTelemetry
            ?? throw new InvalidOperationException("Beam 宽度组合需要请求级诊断记录。");
        List<BeamWidthPortfolioMemberCost> costs = [];
        BeamWidthPortfolioBaseline baseline = default;
        bool baselineObserved = false;
        long expandedByMembers = 0;
        BeamPortfolioExperiment? experiment = policy.PortfolioExperiment;
        SolverResult? baselineResult = null;
        SolverResult? incumbent = initialPlanIncumbent;
        double[]? pendingFeatures = null;
        string pendingDecision = "Observe";
        string solverAssemblyId = typeof(CombatSearchCoordinator).Module.ModuleVersionId.ToString();
        string gameAssemblyId = typeof(CombatState).Module.ModuleVersionId.ToString();
        bool hasReachablePower = root.PlayerCardIds.Any(
            PowerCardValuationModels.Registry.ContainsCardId);
        // Respect explicit portfolio layouts/experiments and the separately enabled novelty pass.
        // This is exactly the measured no-plain-baseline + bounded-refinement combination.
        bool useReallocation = profile.ReallocatedRefinementPortfolio
            && policy.UseBeamWidthPortfolio && !policy.UseNoveltyPortfolio
            && !profile.AdaptiveNoveltyRefinement
            && profile.ContextualRanking == null && profile.BeamWeightPerturbation == null
            && !profile.ContinuousThreatRanking && !profile.BaseScoreTacticalTies
            && !profile.BaseScoreOnly && !profile.SecondRankBand
            && policy.BeamWidthPortfolioWidths is not { Count: > 0 }
            && policy.BeamWidthPortfolioPlainBaselineMember
            && !profile.OffensiveRefinementPortfolio && !profile.BoundedOffensiveRefinementPortfolio;
        if (useReallocation && policy.MeasurePhasePerformance)
            policy.Diagnostics.Info("[CombatSolver/Test] PORTFOLIO_REALLOCATION plain_baseline=False bounded_refinement=True");

        long RemainingMilliseconds()
            => context.RemainingMilliseconds;

        BeamWidthPortfolioRun<SolverResult> RunMember(SolverSearchProfile memberProfile)
        {
            // 精炼成员沿用现有的软时间预算取消：把它收紧到本轮预算的剩余部分，成员自己就会在
            // 预算耗尽时停下，不必另造一套超时。基线成员原样不动。
            long remainingMilliseconds = RemainingMilliseconds();
            long dedicatedPowerMilliseconds = Math.Clamp(
                profile.SoftTimeBudgetMilliseconds / 5L,
                1_000L,
                30_000L);
            SolverSearchProfile effectiveProfile = baselineObserved
                ? memberProfile with
                {
                    SoftTimeBudgetMilliseconds = (int)Math.Clamp(
                        memberProfile.AggressivePowerCommitment
                            ? Math.Max(remainingMilliseconds, dedicatedPowerMilliseconds)
                            : remainingMilliseconds,
                        1,
                        memberProfile.SoftTimeBudgetMilliseconds),
                }
                : memberProfile;
            if (memberProfile.AggressivePowerCommitment
                && policy.MemoryPressureSignal.IsEnabled
                && !policy.MemoryPressureSignal.CanReachCommit(256L * 1024 * 1024))
            {
                policy.MemoryPressureSignal.ReclaimAndContinue(
                    cancellationToken,
                    "power_commitment_portfolio_member");
            }
            SearchRequestWorkSnapshot before = totals.Snapshot();
            long allocatedBefore = GC.GetTotalAllocatedBytes(precise: false);
            long startedMilliseconds = passClock.ElapsedMilliseconds;
            if (policy.MeasurePhasePerformance)
            {
                policy.Diagnostics.Info(
                    $"[CombatSolver/Test] BEAM_WIDTH_PORTFOLIO_MEMBER_START run_index={costs.Count} " +
                    $"beam={effectiveProfile.BeamWidth} second_rank_band={effectiveProfile.SecondRankBand} " +
                    $"base_score_only={effectiveProfile.BaseScoreOnly} " +
                    $"power_commitment={effectiveProfile.AggressivePowerCommitment} " +
                    $"nodes={effectiveProfile.MaxExpandedNodes} " +
                    $"time_ms={effectiveProfile.SoftTimeBudgetMilliseconds}");
            }
            PrimarySearchIncumbent? primaryIncumbent = incumbent == null ? null
                : BuildRefinementPrimarySearchIncumbent(root, policy, memberPotionPolicyOverride, incumbent);
            if (primaryIncumbent is { } bound)
                policy.Diagnostics.Info($"[CombatSolver/Test] BEAM_REFINEMENT_INCUMBENT "
                    + $"member={costs.Count} deficit={bound.StrategicHpDeficit} turn={bound.CombatEndedTurn}");
            SolverResult memberResult = solveMember(effectiveProfile, baselineObserved, primaryIncumbent);
            long memberElapsed = Math.Max(0, passClock.ElapsedMilliseconds - startedMilliseconds);
            long memberAllocated = Math.Max(
                0, GC.GetTotalAllocatedBytes(precise: false) - allocatedBefore);
            long managedHeapAfter = GC.GetTotalMemory(forceFullCollection: false);
            SearchRequestWorkSnapshot after = totals.Snapshot();
            long expanded = after.ExpandedNodes - before.ExpandedNodes;
            expandedByMembers += expanded;
            costs.Add(new BeamWidthPortfolioMemberCost(memberElapsed, memberAllocated, managedHeapAfter));
            bool won = IsCompleteVictory(memberResult);
            bool terminal = won || memberResult.Snapshot.PlayerDead;
            // 与组合器同一条可比性规则。撞节点上限又没到终局的结果不参与质量比较，
            // 否则它既会污染后续成员的 improved 标签，也会让 incumbent 不再代表当前最佳；
            // 被内存回收提前截断的结果同理。
            bool comparable = terminal
                || memberResult.BoundaryReason is not (SearchBoundaryReason.NodeLimit
                    or SearchBoundaryReason.MemoryNoProgress);
            if (experiment != null && baselineObserved && pendingFeatures != null)
            {
                bool improved = comparable && incumbent != null
                    && IsBetterPotionPolicyResult(root, policy, memberResult, incumbent);
                bool usable = won && memberResult.BoundaryReason == SearchBoundaryReason.None
                    && !memberResult.Snapshot.HasRisk && pendingDecision != "UnsupportedSemantics";
                experiment.Observe?.Invoke(new BeamPortfolioObservation(
                    pendingFeatures, pendingDecision, true, improved, usable,
                    memberElapsed, memberResult.BoundaryReason.ToString()));
                pendingFeatures = null;
            }
            if (comparable && (incumbent == null
                || IsBetterPotionPolicyResult(root, policy, memberResult, incumbent)))
                incumbent = memberResult;
            if (!baselineObserved)
            {
                if (experiment != null)
                    baselineResult = memberResult;
                baseline = new BeamWidthPortfolioBaseline(
                    memberResult.BoundaryReason == SearchBoundaryReason.None,
                    IsProvenZeroDamageRoute(root, policy, memberResult),
                    memberElapsed,
                    expanded,
                    effectiveProfile.BeamWidth);
                baselineObserved = true;
                telemetry.RecordFirstRoutePublished(passClock.Elapsed.TotalMilliseconds);
                publishBaseline?.Invoke(memberResult);
            }
            return new BeamWidthPortfolioRun<SolverResult>(
                memberResult,
                expanded,
                after.TransitionCount - before.TransitionCount,
                memberResult.BoundaryReason.ToString(),
                terminal,
                won,
                terminal ? memberResult.ProjectedBattleHpLost : null,
                memberResult.PotionCount)
            {
                StopPortfolio = memberResult.ResultScope != SolverResultScope.SearchCompletion,
                MemoryTruncated = memberResult.BoundaryReason == SearchBoundaryReason.MemoryNoProgress,
            };
        }

        string? RejectMember(BeamWidthPortfolioMemberSpec member)
        {
            if (!baselineObserved)
                return null;
            if (incumbent != null && CanFinishTargetPortfolio(root, policy, profile, incumbent))
                return "AcceptableBattleHpLoss";
            // 能力牌成员走自己的门控（它只要求确实存在可达的能力牌），其余成员走宽度余量门控。
            string? rejection = member.AggressivePowerCommitment
                ? PowerCommitmentPortfolioGate.Reject(hasReachablePower)
                : BeamWidthPortfolioGate.RejectRefinement(
                    baseline, member.BeamWidth, profile.MaxExpandedNodes - expandedByMembers,
                    RemainingMilliseconds(), profile.SoftTimeBudgetMilliseconds);
            // 学习型跳过器未见过能力承诺或进攻精炼成员，不由它裁决这些新策略。
            if (rejection != null || experiment == null || member.AggressivePowerCommitment
                || member.OffensiveRefinement)
                return rejection;
            // 门控已经放行，说明基线没被任何上限截断，因此两边都已经有可比结果。
            SolverResult first = baselineResult
                ?? throw new InvalidOperationException("成员准入已放行，但基线结果未记录。");
            SolverResult best = incumbent
                ?? throw new InvalidOperationException("成员准入已放行，但当前最佳结果未记录。");
            pendingFeatures =
            [
                root.InitialPlayerHp, root.InitialPlayerMaxHp, root.CapturedCardCount,
                root.CapturedPowerCount, root.Enemies.Count, root.StartTurnNumber,
                root.SearchablePotionCount, root.IsActEndingBoss ? 1 : 0,
                profile.BeamWidth, profile.MaxExpandedNodes, profile.MaxCardBranchesPerNode,
                profile.MaxPileChoiceBranchesPerAction, profile.MaxHandChoiceBranchesPerAction,
                IsCompleteVictory(first) ? 1 : 0, first.ProjectedBattleHpLost,
                first.BestNode.ActionCount, first.CombatEndedTurn ?? 0,
                baseline.ExpandedNodes, first.TransitionCount, baseline.ElapsedMilliseconds,
                best.ProjectedBattleHpLost, best.PotionCount,
                (double)(profile.MaxExpandedNodes - expandedByMembers) / profile.MaxExpandedNodes,
                Math.Max(0d, (double)RemainingMilliseconds() / profile.SoftTimeBudgetMilliseconds),
                (double)member.BeamWidth / profile.BeamWidth,
                member.SecondRankBand ? 1 : 0, member.BaseScoreOnly ? 1 : 0,
                policy.MaxDegreeOfParallelism,
                policy.EffectiveHasGrowthTargets ? 1 : 0, policy.RelicTargets.Count,
                policy.TheftPolicy == null ? 0 : 1,
                policy.PotionStrategy.HasForcedDirectives ? 1 : 0,
            ];
            // The label is the production comparator, so policy shape does not disqualify an
            // observation; it becomes input. Only captures that change simulation fidelity do.
            bool eligible = IsCompleteVictory(first) && !first.Snapshot.HasRisk
                && !policy.UseNoveltyPortfolio && policy.BeamWidthPortfolioWidths == null
                && policy.BeamWidthPortfolioPlainBaselineMember && !useReallocation
                && root.CapturedRunModSubscriberCount == 0 && root.CapturedCombatModSubscriberCount == 0
                && !root.CapturedBaseLibCardModifiers;
            pendingDecision = !eligible ? "UnsupportedSemantics"
                : experiment.Model?.Decide(pendingFeatures, solverAssemblyId, gameAssemblyId) ?? "Observe";
            if (experiment.Model != null)
                policy.Diagnostics.Info($"[CombatSolver/Test] PORTFOLIO_SELECTOR_DECISION model={experiment.Model.ModelId} member={member} decision={pendingDecision}");
            if (pendingDecision != "LearnedNoImprovement")
                return null;
            experiment.Observe?.Invoke(new BeamPortfolioObservation(
                pendingFeatures, pendingDecision, false, null, null, 0, null));
            pendingFeatures = null;
            return pendingDecision;
        }

        IReadOnlyList<BeamWidthPortfolioMemberSpec> builtInMembers = BeamWidthPortfolio.ProductionMembers(
            profile.BeamWidth,
            policy.UseBeamWidthPortfolio ? policy.BeamWidthPortfolioWidths : [profile.BeamWidth],
            policy.BeamWidthPortfolioPlainBaselineMember && !useReallocation,
            includePowerCommitmentMember: hasReachablePower,
            useOffensiveRefinement: profile.OffensiveRefinementPortfolio,
            appendBoundedOffensiveRefinement: profile.BoundedOffensiveRefinementPortfolio || useReallocation);
        BeamWidthPortfolioOutcome<SolverResult> outcome = policy.UseBeamWidthPortfolio || hasReachablePower
            ? BeamWidthPortfolio.Run(
                policy.DevelopmentStrategy?.OrganizeMembers(builtInMembers) ?? builtInMembers,
                profile.MaxExpandedNodes,
                profile,
                RunMember,
                (candidate, current) => IsBetterPotionPolicyResult(root, policy, candidate, current),
                RejectMember,
                policy.Diagnostics.Info)
            : SingleMemberOutcome(profile, RunMember);
        RecordPortfolioMembers(policy, telemetry, outcome, costs);
        // 组合路径也要出阶段表：novelty 分支那条打印覆盖不到这里，于是开了 MeasurePhasePerformance
        // 的组合跑批拿不到逐阶段耗时/分配归属。
        if (policy.MeasurePhasePerformance)
            policy.Diagnostics.Info(SolverDiagnostics.DescribeSearchPhasePerformance(outcome.Selected));
        return initialPlanIncumbent != null
            && IsBetterPotionPolicyResult(root, policy, initialPlanIncumbent, outcome.Selected)
                ? initialPlanIncumbent : outcome.Selected;
    }

    /// <summary>
    /// 组合关闭时的一条成员明细。求解走请求自己的 Profile 实例，可比性与选中理由按组合器同一条
    /// 规矩判定，A/B 才能并排读同一张表。
    /// </summary>
    private static BeamWidthPortfolioOutcome<SolverResult> SingleMemberOutcome(
        SolverSearchProfile profile,
        Func<SolverSearchProfile, BeamWidthPortfolioRun<SolverResult>> runMember)
    {
        BeamWidthPortfolioRun<SolverResult> run = runMember(profile);
        bool comparable = run.Terminal
            || (!run.MemoryTruncated
                && !string.Equals(
                    run.Termination, BeamWidthPortfolio.NodeLimitTermination, StringComparison.Ordinal));
        string selectionReason = run.StopPortfolio
            ? BeamWidthPortfolio.SelectionStopped
            : comparable
                ? BeamWidthPortfolio.SelectionBest
                : BeamWidthPortfolio.SelectionBaselineFallback;
        BeamWidthPortfolioMember member = new(
            profile.BeamWidth,
            profile.SecondRankBand,
            profile.BaseScoreOnly,
            profile.AggressivePowerCommitment,
            profile.MaxExpandedNodes,
            Ran: true,
            run.ExpandedNodes,
            run.TransitionCount,
            run.Termination,
            run.Terminal,
            run.Won,
            run.BattleHpLost,
            run.PotionCount,
            Compared: run.StopPortfolio || comparable,
            SkippedReason: run.StopPortfolio || comparable
                ? null
                : run.MemoryTruncated
                    ? BeamWidthPortfolio.SkippedMemoryTruncated
                    : BeamWidthPortfolio.SkippedNodeLimitNotTerminal);
        return new BeamWidthPortfolioOutcome<SolverResult>(
            run.Result, 0, selectionReason, [member], run.ExpandedNodes, run.TransitionCount);
    }

    /// <summary>逐成员一行诊断，同时把明细与托管堆峰值写进请求级记录。</summary>
    private static void RecordPortfolioMembers(
        SearchPolicySnapshot policy,
        BeamWidthPortfolioTelemetry telemetry,
        BeamWidthPortfolioOutcome<SolverResult> outcome,
        IReadOnlyList<BeamWidthPortfolioMemberCost> costs)
    {
        int costIndex = 0;
        for (int index = 0; index < outcome.Members.Count; index++)
        {
            BeamWidthPortfolioMember member = outcome.Members[index];
            BeamWidthPortfolioMemberCost cost = member.Ran
                ? costs[costIndex++]
                : default;
            BeamWidthPortfolioMemberReport report = new(
                member.BeamWidth,
                member.SecondRankBand,
                member.BaseScoreOnly,
                member.AggressivePowerCommitment,
                member.NodeBudget,
                member.Ran,
                Selected: index == outcome.SelectedIndex,
                member.Compared,
                member.SkippedReason,
                member.ExpandedNodes,
                member.TransitionCount,
                member.Termination,
                member.Terminal,
                member.Won,
                member.BattleHpLost,
                member.PotionCount,
                cost.ElapsedMilliseconds,
                cost.AllocatedBytes,
                cost.ManagedHeapBytesAfter)
            { OffensiveRefinement = member.OffensiveRefinement, BoundedRefinement = member.BoundedRefinement };
            telemetry.RecordMember(report);
            policy.Diagnostics.Info(
                $"[CombatSolver/Test] BEAM_WIDTH_PORTFOLIO_MEMBER index={index} " +
                $"beam={report.BeamWidth} second_rank_band={report.SecondRankBand} " +
                $"base_score_only={report.BaseScoreOnly} " +
                $"power_commitment={report.AggressivePowerCommitment} " +
                $"offensive_refinement={report.OffensiveRefinement} " +
                $"bounded_refinement={report.BoundedRefinement} " +
                $"nodes={report.NodeBudget} ran={report.Ran} " +
                $"selected={report.Selected} compared={report.Compared} " +
                $"skipped={report.SkippedReason ?? "-"} " +
                $"elapsed_ms={report.ElapsedMilliseconds} " +
                $"allocated_delta={report.AllocatedBytes} " +
                $"managed_heap_after={report.ManagedHeapBytesAfter} " +
                $"expanded={report.ExpandedNodes} transitions={report.TransitionCount} " +
                $"termination={report.Termination ?? "-"} won={report.Won?.ToString() ?? "-"} " +
                $"battle_hp_lost={report.BattleHpLost?.ToString() ?? "-"} " +
                $"potions={report.PotionCount?.ToString() ?? "-"}");
        }
        if (costIndex != costs.Count)
        {
            throw new InvalidOperationException(
                $"组合成员明细与实测开销条数不一致：明细 {costIndex} 条，实测 {costs.Count} 条。");
        }
    }

    /// <summary>
    /// 基线是否已经拿到「证明最优」的那一类结果：零战损、零主动用药、没卖血、满血且最大生命没掉。
    /// 与搜索里 <c>ProvenZeroDamage</c> 提前收手的条件同一套，只是从返回结果上复算，不在搜索里加观察点。
    /// </summary>
}

src/Search/CombatSearchCoordinator.PlanS.source:
namespace CombatSolver;

internal static partial class CombatSearchCoordinator
{
    private const int MaximumPlanCommitments = 4;
    private const int MaximumDiscoveredPlanCommitments = 18;

    private readonly record struct PlanMemberExecution(
        int MaximumNodes,
        int MaximumMilliseconds,
        bool AggressivePowerCommitment,
        SolverPotionPolicy? PotionPolicyOverride,
        int? MaximumPotionUses,
        bool AllowUnsatisfiedPotion);

    private static SolverResult RunPlanSearchPass(SearchPassContext context, SolverResult baseline)
    {
        if (ReferenceEquals(context.PlanDiscovery.EarlyOpeningPlanProfile, context.Profile)
            || baseline.ResultScope != SolverResultScope.SearchCompletion
            || context.Policy.PotionStrategy.HasForcedDirectives
            || IsProvenZeroDamageRoute(context.Root, context.Policy, baseline)
            || IsCompleteVictory(baseline)
                && baseline.ProjectedBattleHpLost < SolverWeights.PotionMinimumHpSaved * 3)
            return baseline;

        IReadOnlyList<PlanCommitment> plans = DiscoverOpeningPlanCommitments(context);
        context.PlanDiscovery.OpeningPlanCount = plans.Count;
        if (plans.Count == 0)
            return baseline;

        return RunOpeningPlans(context, baseline, plans)!;
    }

    private static SolverResult? TryRunOpeningPlanIncumbent(
        SearchPassContext context, SolverPotionPolicy? potionPolicyOverride)
    {
        SearchPolicySnapshot policy = context.Policy;
        if (!CanRunOpeningPlanIncumbent(context.Root, policy, potionPolicyOverride))
            return null;
        IReadOnlyList<PlanCommitment> plans = DiscoverOpeningPlanCommitments(context);
        if (plans.Count == 0)
            return TryRunNarrowOpeningIncumbent(context, potionPolicyOverride);
        if (plans.Any(plan => plan.UsesPotion))
            return null;
        policy.Diagnostics.Info("[CombatSolver/Test] EARLY_OPENING_PLAN_INCUMBENT start");
        SolverResult? result = RunOpeningPlans(context, null, plans);
        if (result != null && (result.ResultScope != SolverResultScope.SearchCompletion
            || BuildRefinementPrimarySearchIncumbent(context.Root, policy, potionPolicyOverride, result) != null))
        {
            context.PlanDiscovery.OpeningPlanCount = plans.Count;
            context.PlanDiscovery.EarlyOpeningPlanProfile = context.Profile;
            return result;
        }
        return null;
    }

    internal static bool CanRunOpeningPlanIncumbent(CombatRootSnapshot root,
        SearchPolicySnapshot policy, SolverPotionPolicy? potionPolicyOverride)
    {
        // Broad known-source eligibility permits pruning after a victory is found;
        // it does not establish that a speculative plan search is cheap enough to
        // run before the primary member. Keep the existing certified-root schedule.
        if (!root.CanCertifyRemainingHealing
            || !policy.UseBeamWidthPortfolio
            || policy.UseNoveltyPortfolio || policy.IncludeTurnSetup
            || policy.PortfolioExperiment != null || policy.DevelopmentStrategy != null
            || policy.DisableRefinementIncumbentForTesting || policy.DisableOpeningPlanIncumbentForTesting
            || policy.EffectiveHasGrowthTargets
            || policy.RelicTargets.Count != 0 && !CombatBeamSolver.CanUseStrictHpRelicBound(root, policy)
            || policy.PotionStrategy.HasForcedDirectives
            || (potionPolicyOverride ?? policy.PotionPolicy)
                is not (SolverPotionPolicy.Disabled or SolverPotionPolicy.Smart))
            return false;
        return true;
    }

    private static SolverResult? TryRunNarrowOpeningIncumbent(
        SearchPassContext context, SolverPotionPolicy? potionPolicyOverride)
    {
        if (!context.Root.UsesComponentHealingCertificate
            || context.Policy.FixedBudget || context.Profile.BeamWidth < 64
            || context.Profile.SoftTimeBudgetMilliseconds < 30_000)
            return null;
        SearchBudgetWindow window = context.Budget.RequestWindow(context.Profile);
        if (!window.CanStart(7_000))
            return null;
        context.PlanDiscovery.NarrowOpeningIncumbentAttempted = true;
        SolverSearchProfile pilot = window.Limit(context.Profile, 60_000, 20_000, 2_000)
            with { BeamWidth = Math.Max(8, context.Profile.BeamWidth / 16) };
        SolverResult result = new CombatBeamSolver(context.Root, context.DisplayNames,
            context.BattleDamage, context.Policy, context.CancellationToken, context.ProgressCallback,
            pilot, potionPolicyOverride: SolverPotionPolicy.Disabled,
            directSearchPurpose: DirectSearchPurpose.NarrowOpeningIncumbent).Solve();
        bool qualified = BuildRefinementPrimarySearchIncumbent(context.Root, context.Policy,
            potionPolicyOverride, result) != null;
        context.Policy.Diagnostics.Info($"[CombatSolver/Test] NARROW_OPENING_INCUMBENT "
            + $"qualified={qualified} won={IsCompleteVictory(result)} hp_lost={result.ProjectedBattleHpLost} "
            + $"beam={pilot.BeamWidth} expanded={result.ExpandedNodes} elapsed_ms={result.Elapsed.TotalMilliseconds:F1}");
        return qualified ? result : null;
    }

    private static SolverResult? RunOpeningPlans(
        SearchPassContext context, SolverResult? baseline, IReadOnlyList<PlanCommitment> plans)
    {
        SearchPolicySnapshot policy = context.Policy;
        SolverResult? selected = baseline;
        FrontierContinuationScheduler scheduler = new(context);
        int attempted = 0;
        List<PlanCommitment> scheduled = [];
        foreach (int priority in plans.Select(plan => plan.Priority).Distinct()
                     .OrderByDescending(priority => priority))
        {
            PlanCommitment[][] payoffGroups = plans.Where(plan => plan.Priority == priority)
                .GroupBy(plan => plan.Payoff.SourceId)
                .Select(group => group.ToArray())
                .ToArray();
            for (int rank = 0; scheduled.Count < MaximumPlanCommitments; rank++)
            {
                bool found = false;
                foreach (PlanCommitment[] payoffGroup in payoffGroups)
                {
                    if (rank >= payoffGroup.Length)
                        continue;
                    found = true;
                    scheduled.Add(payoffGroup[rank]);
                    if (scheduled.Count == MaximumPlanCommitments)
                        break;
                }
                if (!found)
                    break;
            }
            if (scheduled.Count == MaximumPlanCommitments)
                break;
        }
        foreach (PlanCommitment plan in scheduled)
        {
            if (!TryRunPlanMember(context, scheduler, plan,
                    new PlanMemberExecution(60_000, 20_000,
                        plan.Kind == PlanCommitmentKind.CopyPower,
                        plan.UsesPotion ? SolverPotionPolicy.RequireAtLeastOne
                            : SolverPotionPolicy.Disabled,
                        plan.UsesPotion ? 1 : 0,
                        AllowUnsatisfiedPotion: true),
                    out SolverResult? candidate, selected))
                break;
            attempted++;
            if (candidate == null)
                continue;
            if (candidate.ResultScope != SolverResultScope.SearchCompletion)
                return candidate;
            if (baseline == null && BuildRefinementPrimarySearchIncumbent(context.Root, policy,
                    SolverPotionPolicy.Disabled, candidate) == null)
                continue;
            PopulateSingleSessionTotals(candidate);
            bool improved = selected == null
                || IsBetterPotionPolicyResult(context.Root, policy, candidate, selected);
            if (improved)
                selected = candidate;
            policy.Diagnostics.Info(
                $"[CombatSolver/Test] PLAN_SEARCH_MEMBER kind={plan.Kind} " +
                $"payoff={plan.Payoff.SourceId} potion={plan.UsesPotion} " +
                $"prefix={string.Join(',', plan.Prefix.Select(action =>
                    action.Kind == PlanActionKind.UsePotion
                        ? $"P:{action.PotionId}" + (action.Choice is { Cards.Count: > 0 } potionChoice
                            ? $"[{string.Join('+', potionChoice.Cards.Select(card => card.CardId))}]" : "")
                        : $"C:{action.CardId}" + (action.Choice is { Cards.Count: > 0 } choice
                            ? $"[{string.Join('+', choice.Cards.Select(card => card.CardId))}]" : "")))} " +
                $"opening={string.Join(',', candidate.BestNode.Actions
                    .TakeWhile(action => action.Turn <= context.Root.StartTurnNumber + 1)
                    .Take(16).Select(action => action.Kind == PlanActionKind.UsePotion
                        ? $"P:{action.PotionId}"
                        : action.Kind == PlanActionKind.PlayCard ? $"C:{action.CardId}" : "E"))} " +
                $"won={IsCompleteVictory(candidate)} hp_lost={candidate.ProjectedBattleHpLost} " +
                $"expanded={candidate.ExpandedNodes} selected={improved}");
            if (selected != null && IsProvenZeroDamageRoute(context.Root, policy, selected))
                break;
        }
        policy.Diagnostics.Info(
            $"[CombatSolver/Test] PLAN_SEARCH result candidates={plans.Count} " +
            $"attempted={attempted} selected_hp_lost={selected?.ProjectedBattleHpLost.ToString() ?? "-"}");
        return selected;
    }

    private static SolverResult RunDeferredPowerPlanSearchPass(
        SearchPassContext context, SolverResult baseline)
    {
        if (context.PlanDiscovery.OpeningPlanCount != 0
            || baseline.ResultScope != SolverResultScope.SearchCompletion
            || context.Policy.PotionStrategy.HasForcedDirectives
            || context.Policy.Interaction?.CurrentTakeoverRequest != null
            || baseline.ProjectedBattleHpLost < SolverWeights.PotionMinimumHpSaved * 3
            || !context.Root.PlayerCardIds.Any(PowerCardValuationModels.Registry.ContainsCardId))
            return baseline;

        SearchBudgetWindow scoutWindow = context.Budget.RequestWindow(context.Profile);
        if (!scoutWindow.CanStart(45_000))
            return baseline;

        List<EarlyTurnFrontierCandidate> frontiers = [];
        SolverSearchProfile scoutProfile = scoutWindow.Limit(context.Profile,
            maximumNodes: 25_000, maximumMilliseconds: 8_000,
            reserveMilliseconds: 2_000) with
        {
            StopPortfolioAtHpTarget = false,
        };
        FrontierContinuationScheduler scheduler = new(context);
        scheduler.Dispatch(new ContinuationSearchRequest(context,
            ContinuationPurpose.PlanCommitment, [], scoutProfile,
            SolverPotionPolicy.Disabled, 0, null)
        {
            EarlyTurnScoutDepth = 1,
            EarlyTurnScoutObserver = (turns, candidates) =>
            {
                if (turns == 1)
                    frontiers.AddRange(candidates);
            },
        });

        CombatBeamSolver builder = new(context.Root, context.DisplayNames,
            context.BattleDamage, context.Policy, context.CancellationToken,
            context.ProgressCallback, context.Profile);
        PlanCommitment? plan = null;
        int inspected = 0;
        foreach (EarlyTurnFrontierCandidate frontier in frontiers.Take(8))
        {
            inspected++;
            PlanAction? power = builder.BuildPowerActionsAfterPrefix(frontier.Actions)
                .Select(action => (Action: action,
                    Registered: PowerCardValuationModels.Registry.TryGetCommitmentDescriptor(
                        action.CardId!, out PowerCommitmentDescriptor descriptor),
                    Descriptor: descriptor))
                .Where(item => item.Registered)
                .OrderByDescending(item => item.Descriptor.Priority)
                .Select(item => item.Action)
                .FirstOrDefault();
            if (power == null)
                continue;
            PlanAction[] prefix = [.. frontier.Actions, power];
            plan = new(PlanCommitmentKind.CrossTurnBenefit, prefix,
                context.Root.StartTurnNumber,
                new PlanPayoffEvidence(PlanPayoffEvidenceKind.CardPlayed,
                    power.CardId!, context.Root.StartTurnNumber),
                UsesPotion: false, Priority: 1);
            break;
        }
        if (plan == null)
        {
            context.Policy.Diagnostics.Info(
                $"[CombatSolver/Test] DEFERRED_POWER_PLAN frontiers={inspected} candidate=false");
            return baseline;
        }

        if (!TryRunPlanMember(context, scheduler, plan,
                new PlanMemberExecution(120_000, 60_000,
                    AggressivePowerCommitment: true,
                    PotionPolicyOverride: null,
                    MaximumPotionUses: null,
                    AllowUnsatisfiedPotion: false),
                out SolverResult? memberResult, baseline))
            return baseline;
        SolverResult candidate = memberResult!;
        if (candidate.ResultScope != SolverResultScope.SearchCompletion)
            return candidate;
        PopulateSingleSessionTotals(candidate);
        bool improved = IsBetterPotionPolicyResult(
            context.Root, context.Policy, candidate, baseline);
        context.Policy.Diagnostics.Info(
            $"[CombatSolver/Test] DEFERRED_POWER_PLAN frontiers={inspected} " +
            $"payoff={plan.Payoff.SourceId} won={IsCompleteVictory(candidate)} " +
            $"hp_lost={candidate.ProjectedBattleHpLost} potions={candidate.PotionCount} " +
            $"expanded={candidate.ExpandedNodes} selected={improved}");
        return improved ? candidate : baseline;
    }

    private static bool TryRunPlanMember(
        SearchPassContext context,
        FrontierContinuationScheduler scheduler,
        PlanCommitment plan,
        PlanMemberExecution execution,
        out SolverResult? candidate,
        SolverResult? incumbent = null)
    {
        SearchBudgetWindow window = context.Budget.RequestWindow(context.Profile);
        if (!window.CanStart(7_000))
        {
            candidate = null;
            return false;
        }
        SolverSearchProfile memberProfile = window.Limit(context.Profile,
            maximumNodes: execution.MaximumNodes,
            maximumMilliseconds: execution.MaximumMilliseconds,
            reserveMilliseconds: 2_000) with
        {
            AggressivePowerCommitment = execution.AggressivePowerCommitment,
        };
        ContinuationSearchRequest request = new(context,
            ContinuationPurpose.PlanCommitment, plan.Prefix, memberProfile,
            execution.PotionPolicyOverride, execution.MaximumPotionUses, null)
        {
            Commitment = plan,
            PrimaryIncumbent = incumbent is null ? null : BuildPlanMemberPrimaryIncumbent(
                context.Root, context.Policy, execution.PotionPolicyOverride, incumbent),
        };
        candidate = execution.AllowUnsatisfiedPotion
            ? scheduler.DispatchOptional(request, "PlanCommitment")
            : scheduler.Dispatch(request);
        return true;
    }

    internal static PrimarySearchIncumbent? BuildPlanMemberPrimaryIncumbent(
        CombatRootSnapshot root, SearchPolicySnapshot policy,
        SolverPotionPolicy? potionPolicyOverride, SolverResult incumbent)
        => root.UsesComponentHealingCertificate
            && policy.TheftPolicy != SolverTheftPolicy.PreserveResources
                ? BuildRefinementPrimarySearchIncumbent(root, policy, potionPolicyOverride, incumbent)
                : null;

    private static IReadOnlyList<PlanCommitment> DiscoverOpeningPlanCommitments(
        SearchPassContext context)
    {
        CombatRootSnapshot root = context.Root;
        bool hasPower = root.PlayerCardIds.Any(PowerCardValuationModels.Registry.ContainsCardId);
        CombatBeamSolver builder = new(root, context.DisplayNames, context.BattleDamage,
            context.Policy, context.CancellationToken, context.ProgressCallback, context.Profile,
            potionPolicyOverride: SolverPotionPolicy.RequireAtLeastOne,
            maximumPotionUses: 1);
        DeferredCopyPlanRule[] copyRules = PlanMechanismRegistry.Default.DeferredCopies
            .Where(rule => builder.ContainsChoiceEffectInRoot(rule.Effect))
            .ToArray();
        if (copyRules.Length == 0 && !hasPower)
            return [];

        List<PlanCommitment> plans = [];
        HashSet<string> seen = new(StringComparer.Ordinal);
        Dictionary<(PlanCommitmentKind Kind, string Payoff), int> perPayoff = [];
        void Add(PlanCommitmentKind kind, PlanAction[] prefix, string payoff,
            int priority, int payoffTurnDelay = 1)
        {
            if (plans.Count >= MaximumDiscoveredPlanCommitments
                || perPayoff.GetValueOrDefault((kind, payoff)) >= 2
                || !seen.Add(PowerPrefixKey(prefix)))
                return;
            bool usesPotion = prefix.Any(action => action.Kind == PlanActionKind.UsePotion);
            plans.Add(new(kind, prefix, prefix[0].Turn,
                new PlanPayoffEvidence(PlanPayoffEvidenceKind.CardPlayed,
                    payoff, kind == PlanCommitmentKind.PowerCycle
                        ? prefix[0].Turn : checked(prefix[0].Turn + payoffTurnDelay)),
                usesPotion, priority));
            perPayoff[(kind, payoff)] = perPayoff.GetValueOrDefault((kind, payoff)) + 1;
        }

        int potionOpenings = 0;
        int setupOpenings = 0;
        int copyOptions = 0;
        if (copyRules.Length > 0 && context.Policy.PotionPolicy != SolverPotionPolicy.Disabled)
        {
            foreach (DeferredCopyPlanRule rule in copyRules)
            {
                IReadOnlyList<PlanAction> selectedPotions = builder.BuildOpeningPlanPotionActions(
                    rule.Effect, maximumActions: 6);
                foreach (PlanAction potion in selectedPotions)
                {
                    potionOpenings++;
                    List<PlanAction[]> openings = [[potion]];
                    openings.AddRange(builder.BuildOpeningHandSetupActions([potion],
                            maximumActions: 5,
                            desiredFollowUpEffect: rule.Effect)
                        .Select(setup => new[] { potion, setup }));
                    setupOpenings += openings.Count - 1;
                    foreach (PlanAction[] opening in openings)
                    {
                        foreach (PlanAction copy in builder.BuildOpeningCopyActionsAfterPrefix(
                                     opening, maximumPowerTargets: 3, maximumActions: 8,
                                     desiredEffect: rule.Effect))
                        {
                            copyOptions++;
                            string copiedCardId = copy.Choice!.Cards[0].CardId;
                            bool copiedPower = PowerCardValuationModels.Registry.ContainsCardId(copiedCardId);
                            PlanAction[] copyPrefix = [.. opening, copy];
                            if (copiedPower)
                            {
                                PlanAction? originalPower = builder.BuildPowerActionsAfterPrefix(copyPrefix)
                                    .FirstOrDefault(action => action.CardId == copiedCardId);
                                if (originalPower != null)
                                    Add(PlanCommitmentKind.CopyPower,
                                        [.. copyPrefix, originalPower], copiedCardId,
                                        priority: 4, payoffTurnDelay: rule.PayoffTurnDelay);
                            }
                            Add(copiedPower ? PlanCommitmentKind.CopyPower
                                    : PlanCommitmentKind.CopyCard,
                                copyPrefix, copiedCardId, copiedPower ? 3 : 2,
                                rule.PayoffTurnDelay);
                            if (plans.Count >= MaximumDiscoveredPlanCommitments)
                                break;
                        }
                        if (plans.Count >= MaximumDiscoveredPlanCommitments)
                            break;
                    }
                    if (plans.Count >= MaximumDiscoveredPlanCommitments)
                        break;
                }
                if (plans.Count >= MaximumDiscoveredPlanCommitments)
                    break;
            }
        }
        if (hasPower && plans.Count < MaximumDiscoveredPlanCommitments)
        {
            foreach (PlanAction power in builder.BuildOpeningPowerActions()
                         .Where(action => PowerCardValuationModels.Registry.ContainsCardId(action.CardId!))
                         .Take(2))
            {
                foreach (PlanAction setup in builder.BuildOpeningHandSetupActions([power]).Take(2))
                    Add(PlanCommitmentKind.PowerCycle, [power, setup], power.CardId!, priority: 1);
            }
            foreach (PlanAction setup in builder.BuildOpeningHandSetupActions().Take(2))
            {
                foreach (PlanAction power in builder.BuildPowerActionsAfterPrefix([setup])
                             .Where(action => PowerCardValuationModels.Registry.ContainsCardId(action.CardId!))
                             .Take(1))
                    Add(PlanCommitmentKind.PowerCycle, [setup, power], power.CardId!, priority: 1);
            }
        }
        context.Policy.Diagnostics.Info(
            $"[CombatSolver/Test] PLAN_SEARCH_DISCOVERY count={plans.Count} " +
            $"potion_openings={potionOpenings} setup_openings={setupOpenings} copy_options={copyOptions} " +
            $"copy={plans.Count(plan => plan.Kind is PlanCommitmentKind.CopyPower or PlanCommitmentKind.CopyCard)} " +
            $"power_cycle={plans.Count(plan => plan.Kind == PlanCommitmentKind.PowerCycle)}");
        return plans;
    }
}

