        foreach (string id in new[] { "VEILPIERCER", "ARSENAL", "DEFEND_DEFECT", "BUNDLE_OF_JOY" })
            await InjectCardAsync(live, player, new() { CardId = id, Pile = "Hand" });
        await CreatureCmd.SetMaxHp(live.Enemies.Single(), 200);
        await CreatureCmd.SetCurrentHp(live.Enemies.Single(), 200);
        SetEnergy(player, 100);
        var root = CombatRootSnapshot.Capture(live);
        if (root.UsesComponentHealingCertificate || !root.UsesPruningComponentHealingCertificate)
            throw new InvalidOperationException("Four-card fresh root did not separate proof and schedule.");
        var parent = root.ForkSimulator();
        string before = DescribeContinuationContractState(parent, root, player);
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        var nodes = await Task.Run(() => CombatBeamSolver.PruningCardsForTesting(root,
            SolverDisplayNames.Capture(live), BattleDamageTracker.Observe(live), policy, token), token);
        if (DescribeContinuationContractState(parent, root, player) != before
            || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
            throw new InvalidOperationException("Card proof touched frozen parent/live.");
        foreach (var node in nodes)
        {
            var native = player.PlayerCombatState!.Hand.Cards.First(card => card.Id.Entry == node.Action!.CardId);
            GameAction action = await SolverController.EnqueueAndCaptureActionAsync(
                queued => queued is PlayCardAction play && ReferenceEquals(play.NetCombatCard.ToCardModelOrNull(), native),
                () => { if (!native.TryManualPlay(native.TargetType == TargetType.AnyEnemy ? live.Enemies.Single() : null))
                    throw new InvalidOperationException("Native card refused."); }, token);
            await action.CompletionTask.WaitAsync(token);
            var expected = ContinuationStamp.CapturePredicted(player, node.Snapshot.Simulator,
                node.Turn, root.Forecast, root.StartTurnNumber);
            var actual = ContinuationStamp.CaptureLive(live);
            if (actual.StateText != expected.StateText)
                throw new InvalidOperationException("Native card full-state mismatch " + node.Action!.CardId + ": "
                    + string.Join("; ", expected.DescribeDifferences(actual, 8)));
        }
        if (DescribeContinuationContractState(parent, root, player) != before)
            throw new InvalidOperationException("Native card execution touched frozen parent.");
        foreach (var node in nodes) node.Snapshot.ReleaseSimulator();
    }
'''
s=s[:a]+method+s[a:]
a=s.rindex('\n}')
helper='''
    internal static IReadOnlyList<SearchNode> PruningCardsForTesting(CombatRootSnapshot root,
        SolverDisplayNames names, BattleDamageSnapshot damage, SearchPolicySnapshot policy, CancellationToken token)
    {
        using var isolation = SimulationNotificationIsolation.Enter();
        var solver = new CombatBeamSolver(root, names, damage, policy with { VerifyIncrementalSearch = true }, token,
            potionPolicyOverride: SolverPotionPolicy.Disabled);
        var opening = CreateOpeningSearchSeed(solver.Replay([]));
        List<SearchNode> nodes = [];
        SearchNode current = opening;
        foreach (string id in new[] { "VEILPIERCER", "ARSENAL", "DEFEND_DEFECT", "BUNDLE_OF_JOY" })
            nodes.Add(current = solver.CostChildForTesting(current,
                solver.PrepareCardActions(current).First(a => a.Action.CardId == id).Action));
        opening.Snapshot.ReleaseSimulator();
        return nodes;
    }
'''
